head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > readOnly]<br/>특정 Body Cell 이 아닌 Body Column 의 읽기전용(readonly) 상태를 설정합니다.",
    "validation" : [
        "id 속성으로 DataList 의 Column 과 바인드 되지 않은 Column 은 readOnly 속성이 true 로 자동 설정됩니다.",
        "id 속성으로 DataList 의 Column 과 바인드된 Column 은 readOnly 속성이 자동 설정되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// getColumnReadOnly : Column 레벨 readOnly 속성 관측
//  - col1(0), col2(1) : DataList 바인드 Column -> 자동 readonly 아님 ('')
//  - col3(2), col4(3) : DataList 미바인드 Column -> readOnly 자동 true
scwin.btn_getColumnReadOnly_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("col1(바인드) getColumnReadOnly : '" + target1.getColumnReadOnly(0) + "'");
    bottom.setReturnValue("col2(바인드) getColumnReadOnly : '" + target1.getColumnReadOnly(1) + "'");
    bottom.setReturnValue("col3(미바인드) getColumnReadOnly : " + target1.getColumnReadOnly(2));
    bottom.setReturnValue("col4(미바인드) getColumnReadOnly : " + target1.getColumnReadOnly(3));
}



// getCellReadOnly : Cell 레벨 readOnly 관측 (Column 자동 readonly 여부 대조)
//  - 바인드 Column(col1) Cell(0) 은 자동 readonly 대상 아님, 미바인드 Column(col3) Cell(0) 은 자동 readonly
scwin.btn_getCellReadOnly_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("col1(바인드) Cell(0) getCellReadOnly : '" + target1.getCellReadOnly(0, 0) + "'");
    bottom.setReturnValue("col3(미바인드) Cell(0) getCellReadOnly : '" + target1.getCellReadOnly(0, 2) + "'");
}



// 셀 더블클릭 시 편집 진입 여부로 자동 readonly 대조
//  - 바인드 Column 셀 : 편집 진입 (isEditing=true)
//  - 미바인드 Column 셀 : 자동 readonly 로 편집 차단 (isEditing=false)
scwin.target1_oncelldblclick = function (row, col) {
    let editing = target1.isEditing();
    wf_body_bottom.getObj("scwin").setReturnValue("oncelldblclick 발생 : Cell(" + row + "," + col + ") isEditing=" + editing);
}
